// 分段线性插值函数（仅计算 zoom）
function getZoomByDistance(distance) {
    // 数据点（按 distance 从小到大排列）
    const dataPoints = [
        { distance: 2.159, zoom: 0 },
        { distance: 10.455, zoom: 1312 },
        { distance: 15.652, zoom: 1522 },
        { distance: 23.565, zoom: 1682 },
    ];

    // 边界情况：小于最小值
    if (distance <= dataPoints[0].distance) {
        return dataPoints[0].zoom;
    }

    // 边界情况：大于最大值
    if (distance >= dataPoints[dataPoints.length - 1].distance) {
        return dataPoints[dataPoints.length - 1].zoom;
    }

    // 查找插值区间并进行线性插值
    for (let i = 0; i < dataPoints.length - 1; i++) {
        const p1 = dataPoints[i];
        const p2 = dataPoints[i + 1];

        if (distance >= p1.distance && distance <= p2.distance) {
            // 计算插值系数
            const t = (distance - p1.distance) / (p2.distance - p1.distance);

            // 线性插值计算 zoom
            const zoom = Math.round(p1.zoom + (p2.zoom - p1.zoom) * t);
            return zoom;
        }
    }
}

